import Foundation

enum AppLocalization {
    static func text(_ english: String, languageRaw: String) -> String {
        let language = AppLanguage(rawValue: languageRaw) ?? .english
        guard language != .english else { return english }
        return translations(for: language)[english] ?? english
    }

    private static func translations(for language: AppLanguage) -> [String: String] {
        switch language {
        case .english:
            return [:]
        case .german:
            return german.merging(germanExtras) { _, new in new }
        case .italian:
            return italian.merging(italianExtras) { _, new in new }
        case .spanish:
            return spanish.merging(spanishExtras) { _, new in new }
        case .french:
            return french.merging(frenchExtras) { _, new in new }
        }
    }

