func appText(_ english: String, _ languageRaw: String) -> String {
    AppLocalization.text(english, languageRaw: languageRaw)
}

func localizedFullMonthName(for month: Int, languageRaw: String) -> String {
    guard (1...12).contains(month) else { return "" }
    let language = AppLanguage(rawValue: languageRaw) ?? .english
    switch language {
    case .english:
        return ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][month - 1]
    case .german:
        return ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"][month - 1]
    case .italian:
        return ["Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno", "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"][month - 1]
    case .spanish:
        return ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"][month - 1]
    case .french:
        return ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"][month - 1]
    }
}

func localizedMemberCount(_ count: Int, languageRaw: String) -> String {
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .spanish:
        return "\(count) \(count == 1 ? "miembro" : "miembros")"
    default:
        return "\(count) \(count == 1 ? "member" : "members")"
    }
}

func localizedIssueCount(_ count: Int, languageRaw: String) -> String {
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .spanish:
        return "\(count) \(count == 1 ? "edición" : "ediciones")"
    default:
        return count == 1 ? appText("1 issue", languageRaw) : "\(count) \(appText("issues", languageRaw))"
    }
}

func localizedMonthCount(_ count: Int, languageRaw: String) -> String {
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .spanish:
        return "\(count) \(count == 1 ? "mes" : "meses")"
    default:
        return "\(count) \(count == 1 ? "month" : "months")"
    }
}

func localizedPostedProgress(posted: Int, total: Int, languageRaw: String) -> String {
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .spanish:
        return "\(posted) de \(max(total, 0)) miembros \(posted == 1 ? "ha publicado" : "han publicado")"
    default:
        return "\(posted) / \(max(total, 0)) members posted"
    }
}

func localizedRemainingCharacters(_ count: Int, languageRaw: String) -> String {
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .spanish:
        return "\(count) \(count == 1 ? "carácter restante" : "caracteres restantes")"
    default:
        return "\(count) characters left"
    }
}

func localizedDisplayDate(_ date: Date, languageRaw: String) -> String {
    let formatter = DateFormatter()
    formatter.dateStyle = .long
    formatter.timeStyle = .none
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .english:
        formatter.locale = Locale(identifier: "en")
    case .german:
        formatter.locale = Locale(identifier: "de")
    case .italian:
        formatter.locale = Locale(identifier: "it")
    case .spanish:
        formatter.locale = Locale(identifier: "es")
    case .french:
        formatter.locale = Locale(identifier: "fr")
    }
    return formatter.string(from: date)
}

func localizedIssueTitle(owner: String, month: Int, languageRaw: String) -> String {
    let monthName = localizedFullMonthName(for: month, languageRaw: languageRaw)
    switch AppLanguage(rawValue: languageRaw) ?? .english {
    case .spanish:
        return "\(owner): edición de \(monthName)"
    default:
        return "\(owner)'s \(monthName) Issue"
    }
}
